       for g in range(0,min(4*f+2,q)+1):
        cells.append((n,l,k,q,e,f,g,S2))
L=set(cells); D=8

# ---- E(Lambda) via R: value sets + tight pairwise monotone bounds ----
vals=[sorted(set(c[i] for c in cells)) for i in range(D)]
