def envelope(i,j):
    m={}
    for c in cells: m[c[j]]=max(m.get(c[j],-10**9), c[i])
    ts=sorted(m); best=-10**9; out={}
    for t in ts:
        best=max(best,m[t]); out[t]=best
    return out
phis={}
for i in range(D):
    for j in range(D):
        if i!=j: phis[(i,j)]=envelope(i,j)
R=0; Rset=[]
for x in product(*vals):
    ok=all(x[i] <= phis[(i,j)][x[j]] for i in range(D) for j in range(D) if i!=j)
    if ok: R+=1
print("|R(Lambda)| =", R, " E(Lambda) =", R-len(L), " R contains Lambda:", R>=976)

# ---- fibre identities: the cylinder factorisation over the transfer q ----
A={q:0 for q in range(4)}; B={q:0 for q in range(4)}
for n in range(1,4):
 for l in range(0,min(n-1,1)+1):
  for k in range(1,min(4*l+2,3)+1):
   for S2 in range(0,k+1):
    for q in range(4):
     if q<=k: A[q]+=1
for e in range(1,4):
 for f in range(0,min(e-1,1)+1):
  for q in range(4):
   B[q]+=min(4*f+2,q)+1
print("A(q):",[A[q] for q in range(4)]," B(q):",[B[q] for q in range(4)])
tot=sum(A[q]*B[q] for q in range(4))
print("sum A(q)*B(q) =",tot," matches |Lambda|:",tot==len(L))
print("sections match figure (33x5, 33x10, 23x15, 8x17):",
