import pdfplumber
def audit(path,label,top=76,bot=64):
    pdf=pdfplumber.open(path)
    H=float(pdf.pages[0].height)
    findings=[]; fills=[]
    for i,pg in enumerate(pdf.pages):
        boxes=[(c['top'],c['bottom']) for c in pg.chars if c['top']>40]
        boxes+=[(im['top'],im['bottom']) for im in pg.images]
        boxes+=[(r['top'],r['bottom']) for r in pg.rects]
        if not boxes: findings.append((i+1,'EMPTY PAGE',700)); continue
        boxes.sort(); merged=[list(boxes[0])]
        for a,b in boxes[1:]:
            if a<=merged[-1][1]+2: merged[-1][1]=max(merged[-1][1],b)
            else: merged.append([a,b])
        gaps=[(merged[j+1][0]-merged[j][1], merged[j][1]) for j in range(len(merged)-1)]
        for g,y in gaps:
            if g>55: findings.append((i+1,'internal gap %dpt'%round(g),g))
        tail=H-bot-merged[-1][1]
        if tail>200 and i+1<len(pdf.pages): findings.append((i+1,'tail %dpt'%round(tail),tail))
        fills.append(sum(b-a for a,b in merged)/(H-top-bot))
    findings.sort(key=lambda x:-x[2])
    print(f"== {label}: pages={len(pdf.pages)} mean fill={sum(fills)/len(fills):.2f} flagged={len(findings)}")
    for f in findings[:12]: print("  p%-4d %s"%(f[0],f[1]))
audit('/mnt/user-data/outputs/The_Method.pdf','CORRECTED')
audit('original.pdf','ORIGINAL')
EOF

