import re
from itertools import product
s=open('BOOK-restored.md',encoding='utf-8').read()
i=s.rindex('# Appendix A'); j=s.rindex('# Appendix B'); A=s[i:j]
rows=re.findall(r'^\s{2,}(A\.\d+)\s{2,}(\S.*?)\s{2,}(\S.*)$',A,re.M)
secs=re.findall(r'^ (A\.\d+)\s+(\S.*)$',A,re.M)
print("ledger rows:",len(rows),"| written-out sections:",len(secs))
named={k:v for k,v in [(r[0],r[1]) for r in rows]}
for k,v in secs: named.setdefault(k,v)
print("distinct named mathematical elements in Appendix A:",len(named))
# status/verification read off the ledger's own wording
ST={'withdrawn':0,'conjectured':1,'measured':2,'verified':3,'proved':4}
VE={'cited':0,'sampled':1,'exhaustive':2}
cells=set(); detail=[]
for r in rows:
    where=r[2].lower()
    st=ST['proved'] if 'in full' in where else (ST['verified'] if 'computed' in where or 'forced' in where else ST['conjectured'])
    ve=VE['exhaustive'] if ('in full' in where or 'computed' in where) else VE['cited']
    cells.add((st,ve)); detail.append((r[0],st,ve))
for k,v in secs:
    if k not in [d[0] for d in detail]:
        cells.add((ST['proved'],VE['exhaustive'])); detail.append((k,ST['proved'],VE['exhaustive']))
def R(X):
    D=2; vals=[sorted({c[i] for c in X}) for i in range(D)]
    def env(a,b):
        m={}
        for c in X: m[c[b]]=max(m.get(c[b],-99),c[a])
        best=-99;o={}
        for t in sorted(m): best=max(best,m[t]); o[t]=best
        return o
    phi={(a,b):env(a,b) for a in range(D) for b in range(D) if a!=b}
    return {x for x in product(*vals) if all(x[a]<=phi[(a,b)][x[b]] for a in range(D) for b in range(D) if a!=b)}
r=R(cells)
print("distinct (status, verification) cells:",len(cells),"| |R| =",len(r),"| E =",len(r)-len(cells))
inv={v:k for k,v in ST.items()}; inv2={v:k for k,v in VE.items()}
for x in sorted(r-cells): print("   admitted & absent:",inv[x[0]],'·',inv2[x[1]])
print("\nelements enumerated:",len(detail),"of the appendix's stated 32; its own fibre table sums to 27")
EOF

