# U4: prove join-closure, and check every meet failure is an upper-bound failure
def T(cap):
    return {(L,S,J) for L in range(cap+1) for S in range(cap+1)
            for J in range(abs(L-S), min(L+S,cap)+1)}
for cap in (8,12,16):
    X=T(cap); L=sorted(X); jf=0; mf_low=mf_up=0
    for i,a in enumerate(L):
        for b in L[i+1:]:
            j=(max(a[0],b[0]),max(a[1],b[1]),max(a[2],b[2]))
