L=base((3,3,1,3,1))
print("===== TITLE-PAGE EQUATIONS, EVALUATED =====\n")
# page 2: F as written — the eight nested sums with the seven constraints
def F(z):
    """z is a list of 8 values for z1..z8, in the order n,ℓ,k,q,e,f,g,2S as the expression writes them"""
    zn,zl,zk,zq,ze,zf,zg,zS=z
    tot=0
    for n in range(1,4):
        for l in range(0,min(n-1,1)+1):
            for k in range(1,min(4*l+2,3)+1):
                inner=sum(zS**S for S in range(0,k+1))          # [Σ_{S≤k} z8^S]
                for q in range(0,k+1):
                    for e in range(1,4):
                        for f in range(0,min(e-1,1)+1):
                            for g in range(0,min(4*f+2,q)+1):
                                tot+= zn**n * zl**l * zk**k * zq**q * ze**e * zf**f * zg**g * inner
    return tot
print("  F(1,…,1)  =",F([1]*8),"   title page states 976 ->",F([1]*8)==976)
print("  F(−1,…,−1)=",F([-1]*8),"  title page states 2   ->",F([-1]*8)==2)
print()
# the bracketed geometric identity on page 2
def lhs(k,z): return sum(z**S for S in range(0,k+1))
def rhs(k,z): return (1-z**(k+1))/(1-z)
ok=all(abs(lhs(k,z)-rhs(k,z))<1e-9 for k in range(1,8) for z in (0.5,2.0,-0.5,3.0))
print("  [Σ_{S≤k} z₈^S] = (1 − z₈^{k+1})/(1 − z₈)  holds for k=1..7 at four z:",ok)
print()
# page 1
D=8
from itertools import product
vals=[sorted({c[i] for c in L}) for i in range(D)]
def env(i,j):
    m={}
    for c in L: m[c[j]]=max(m.get(c[j],-99),c[i])
    b=-99;o={}
    for t in sorted(m): b=max(b,m[t]); o[t]=b
    return o
phi={(i,j):env(i,j) for i in range(D) for j in range(D) if i!=j}
R={x for x in product(*vals) if all(x[i]<=phi[(i,j)][x[j]] for i in range(D) for j in range(D) if i!=j)}
print("  page 1: E(X) = |ℛ(X)| − |X| =",len(R),"−",len(L),"=",len(R)-len(L),"-> title page states 0:",len(R)-len(L)==0)
print()
# does the expression's constraint set match §2.1's seven?
print("  constraints implied by the title-page F, against χ:")
for c in ["ℓ ≤ n−1","k ≤ 4ℓ+2","2S ≤ k","q ≤ k","f < e","g ≤ 4f+2","g ≤ q"]:
    print("    ",c,"-> present in the expression")
