from itertools import combinations, permutations
# the one non-trivial component
E=[1,2,3,4,5,10,13,14,17]
nm={1:'LATTICE',2:'EQUATIONS',3:'CONSISTENCY',4:'REDUNDANCY',5:'ARTEFACT',10:'SCOPE',13:'AGREEMENT',14:'ARITHMETIC',17:'MEASURE'}
prec=[(1,2),(2,3),(3,4),(3,5),(4,5),(2,10),(2,13),(2,14),(5,17)]
le={(i,i) for i in E}|set(prec)
ch=True
while ch:
    ch=False
    for a,b in list(le):
        for c,d in list(le):
            if b==c and (a,d) not in le: le.add((a,d)); ch=True
rel=lambda a,b:(a,b) in le
def linexts():
    out=[]
    def rec(rem,cur):
        if not rem: out.append(tuple(cur)); return
        for x in sorted(rem):
            if all(not rel(y,x) or y==x for y in rem): rec(rem-{x},cur+[x])
    rec(frozenset(E),[])
    return out
LE=linexts()
print(f"component: {len(E)} audits, linear extensions: {len(LE)}")
def inter(exts):
    pairs=set()
    for a,b in permutations(E,2):
        if all(e.index(a)<e.index(b) for e in exts): pairs.add((a,b))
    return pairs
target={(a,b) for a,b in permutations(E,2) if rel(a,b)}
dim=None
for k in (2,3,4):
    found=None
    for combo in combinations(LE,k):
        if inter(combo)==target: found=combo; break
    if found: dim=k; break
print(f"order dimension of the component: {dim}")
print(f"  a realiser of size {dim}:")
for e in found: print("   ",[nm[x] for x in e])
print()
print("whole poset: seven components, three of them 2-chains, three singletons")
print(f"  dim(disjoint union) = max(2, dim of largest) = {max(2,dim)}")
print()
print("so the precedence order is representable in", max(2,dim), "ordered coordinates.")
print("the audit index uses four. two carry the order; the rest carry meaning the order does not.")
