from itertools import product
ST={'withdrawn':0,'conjectured':1,'measured':2,'verified':3,'proved':4}
VE={'cited':0,'sampled':1,'exhaustive':2}; PR={'none found':0,'found':1}
def ok(c):
    st,ve,pr=c
    return not(ve==VE['cited'] and pr!=PR['found']) and not(st>=ST['measured'] and ve<VE['sampled'])
def R(X):
    D=3; vals=[sorted({c[i] for c in X}) for i in range(D)]
    def env(a,b):
        m={}
        for c in X: m[c[b]]=max(m.get(c[b],-99),c[a])
        best=-99;o={}
        for t in sorted(m): best=max(best,m[t]); o[t]=best
        return o
    phi={(a,b):env(a,b) for a in range(D) for b in range(D) if a!=b}
    return {x for x in product(*vals) if all(x[a]<=phi[(a,b)][x[b]] for a in range(D) for b in range(D) if a!=b) and ok(x)}
inv={v:k for k,v in ST.items()};i2={v:k for k,v in VE.items()};i3={v:k for k,v in PR.items()}
def fib(label,cells):
    X={(ST[a],VE[b],PR[c]) for a,b,c in cells}
    r=R(X); e=len(r)-len(X)
    print(f"  {label:34s} elements {len(cells):2d}  cells {len(X)}  E {e}")
