def ident(cap):
    L=base(cap); S=set(L); D=8
    vals=[sorted({c[i] for c in L}) for i in range(D)]
    byr=defaultdict(list)
    for c in L: byr[sum(c)].append(c)
    leq=lambda a,b: all(x<=y for x,y in zip(a,b))
    J=[x for x in L if len([y for y in byr.get(sum(x)-1,[]) if leq(y,x)])==1]
    def env(i,j):
        m={}
        for c in L: m[c[j]]=max(m.get(c[j],-99),c[i])
        b=-99;o={}
        for t in sorted(m): b=max(b,m[t]); o[t]=b
        return o
    phi={(i,j):env(i,j) for i in range(D) for j in range(D) if i!=j}
    R=sum(1 for x in product(*vals) if all(x[i]<=phi[(i,j)][x[j]] for i in range(D) for j in range(D) if i!=j))
    jf=mf=rm=0
    for a,b in combinations(L,2):
        jn=tuple(max(x,y) for x,y in zip(a,b)); mt=tuple(min(x,y) for x,y in zip(a,b))
        if jn not in S: jf+=1
        if mt not in S: mf+=1
        elif jn in S and sum(jn)+sum(mt)!=sum(a)+sum(b): rm+=1
    A=defaultdict(set); B=defaultdict(set)
    for c in L: A[c[3]].add((c[0],c[1],c[2],c[7])); B[c[3]].add((c[4],c[5],c[6]))
